      SUBROUTINE PIVEXCC     COORDINATE TRANSFORMATION AT SECTION EXITC     (USED FOR MISALIGNMENTS)CC ----------------------------------------------------------------------C      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8D.CIN'CC     LOCAL VARIABLESC      INTEGER         J, K, N      REAL            S      REAL            ORT(3,3), XRT(3)C ---------------------------------------------------------------------CC     PIVOT POINT ABOUT MAGNET CENTERC      IF (CHORD) GO TO 100      IF (TMK .EQ. 0) GO TO 200      DO 30 J = 1, 3   30 XR(J) = XR(J) + XT(J)      IF (TMK .EQ. 2) GO TO 150      GO TO 200CC     COORDINATE TRANSFORMATION FOR EXIT FACEC  100 S = 0.0      DO 110 J = 1, 3  110 XRT(J) = XR(J)      DO 115 J = 1, 3  115 XR(J) = 0.0      DO 120 J = 1, 3  120 S = S + XRT(J)**2      XR(3) = SQRT(S)CC     PIVOT POINT AT CHORD MIDPOINTC      IF (TMK .EQ. 1) THEN        DO 130 J = 1, 3  130   XR(J) = 0.5*XR(J)      ELSE IF (TMK .EQ. 2) THEN        DO 135 J = 1, 3  135   XR(J) = 0.0      ENDIFCC     COORDINATE TRANSFORMATION FOR EXIT FACEC  150 DO 160 J = 1, 3      DO 160 K = 1, 3      ORT(J,K) = OR(J,K)  160 CONTINUEC      DO 180 J = 1, 3      DO 180 K = 1, 3      S = 0.0      DO 175 N = 1, 3      S = S + ORT(J,N)*OT(N,K)  175 CONTINUE      OR(J,K) = S  180 CONTINUEC  200 RETURN      END